import{_ as d,o as a,c as r,a3 as e}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"页面渲染策略","description":"","frontmatter":{"title":"页面渲染策略","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/rendering/rendering-strategy.md","filePath":"frontend/decisions/rendering/rendering-strategy.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/rendering/rendering-strategy.md"};function o(l,t,h,n,s,S){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="页面渲染策略" tabindex="-1">页面渲染策略 <a class="header-anchor" href="#页面渲染策略" aria-label="Permalink to &quot;页面渲染策略&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>页面渲染策略决定初始 HTML 在哪里、何时生成，以及后续交互如何接管。CSR、SSR 和 SSG 不是整个站点必须统一选择的三个品牌标签；现代应用通常按路由甚至页面区域组合，并把缓存和再生成作为独立的内容更新策略。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>渲染方式会同时影响可索引内容、首屏响应、个性化、缓存、服务器成本、Hydration 和开发复杂度。只用“SEO 要 SSR”或“后台用 CSR”下结论，会遗漏内容更新频率、用户身份、JavaScript 预算和故障降级。</p><p>决策单位应是具有相同数据和体验约束的一组页面，而不是仓库。首页、商品详情、账户中心和在线编辑器可以采用不同策略。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-页面级硬约束" tabindex="-1">2.1 页面级硬约束 <a class="header-anchor" href="#_2-1-页面级硬约束" aria-label="Permalink to &quot;2.1 页面级硬约束&quot;">​</a></h3><ul><li>搜索引擎或外部预览必须在无需执行客户端 JavaScript 时获得关键内容；</li><li>私有用户数据不得进入共享缓存或静态产物；</li><li>页面必须满足公司的性能、无障碍和浏览器基线；</li><li>内容时效、错误状态和降级行为必须可验证；</li><li>运行环境必须支持所需数据源、身份和区域合规。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较可索引性、首字节时间、最大内容绘制、交互时间、个性化、内容更新频率、缓存命中、服务器容量、实现与排障、第三方脚本和无 JavaScript 降级。</p><p>不要只看 HTML 到达速度。SSR 页面若发送大量 Hydration JavaScript，仍可能很晚才能交互。</p><h2 id="_3-候选策略" tabindex="-1">3. 候选策略 <a class="header-anchor" href="#_3-候选策略" aria-label="Permalink to &quot;3. 候选策略&quot;">​</a></h2><h3 id="_3-1-csr" tabindex="-1">3.1 CSR <a class="header-anchor" href="#_3-1-csr" aria-label="Permalink to &quot;3.1 CSR&quot;">​</a></h3><p>服务器返回应用外壳，浏览器加载 JavaScript 后请求数据并生成主要 UI。适合登录后的高交互工具、内容不可索引且用户会长时间停留的场景。优势是静态托管简单；代价是首屏依赖脚本、数据瀑布和弱设备执行能力。</p><h3 id="_3-2-请求时-ssr" tabindex="-1">3.2 请求时 SSR <a class="header-anchor" href="#_3-2-请求时-ssr" aria-label="Permalink to &quot;3.2 请求时 SSR&quot;">​</a></h3><p>每个请求在服务端生成 HTML，浏览器再 Hydration 或仅激活局部交互。适合可索引且需要请求级个性化、授权或实时数据的页面。它增加服务器容量、缓存分层、双端运行差异和 Hydration 风险。</p><h3 id="_3-3-构建时-ssg" tabindex="-1">3.3 构建时 SSG <a class="header-anchor" href="#_3-3-构建时-ssg" aria-label="Permalink to &quot;3.3 构建时 SSG&quot;">​</a></h3><p>在构建阶段生成静态 HTML，可由 CDN 长期缓存。适合内容有限、公开、变更频率可接受的文档和营销页。页面数量或更新频率过高时，全量构建和内容陈旧会成为瓶颈。</p><h3 id="_3-4-混合与局部渲染" tabindex="-1">3.4 混合与局部渲染 <a class="header-anchor" href="#_3-4-混合与局部渲染" aria-label="Permalink to &quot;3.4 混合与局部渲染&quot;">​</a></h3><p>路由可以分别使用 SSG、SSR 和 CSR；同一页面也可以先返回静态或服务端主体，再让客户端加载私有交互区域。混合策略能贴合真实约束，但要求框架、缓存和监控能够区分每类路径。</p><h3 id="_3-5-再生成是更新策略" tabindex="-1">3.5 再生成是更新策略 <a class="header-anchor" href="#_3-5-再生成是更新策略" aria-label="Permalink to &quot;3.5 再生成是更新策略&quot;">​</a></h3><p>定时再生成、按需失效和常被称为 ISR 的能力，解决的是静态页面何时更新，不是第四种基本渲染地点。选择它时需明确允许陈旧多久、谁触发失效、并发再生成如何去重、失败时继续提供旧页面还是报错。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>CSR</th><th>请求时 SSR</th><th>SSG</th><th>静态页按需再生成</th></tr></thead><tbody><tr><td>公开内容可索引</td><td>依赖爬虫执行能力</td><td>好</td><td>好</td><td>好</td></tr><tr><td>请求级个性化</td><td>客户端获取</td><td>强</td><td>不适合</td><td>仅限非私有变体</td></tr><tr><td>CDN 缓存</td><td>外壳容易</td><td>需按数据设计</td><td>最容易</td><td>容易但需失效</td></tr><tr><td>服务器成本</td><td>低</td><td>高</td><td>低</td><td>中</td></tr><tr><td>内容新鲜度</td><td>取决于 API</td><td>高</td><td>取决于构建</td><td>取决于失效策略</td></tr><tr><td>双端复杂度</td><td>低</td><td>高</td><td>中</td><td>中至高</td></tr><tr><td>Hydration</td><td>通常整个应用</td><td>通常需要</td><td>有交互时需要</td><td>有交互时需要</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例是电商 Web：营销首页每天更新，类目页约 2 万个且每小时有库存变化，商品详情 80 万个，账户中心完全私有，购物车要求高交互。</p><p>推荐按页面组合：</p><table tabindex="0"><thead><tr><th>页面</th><th>策略</th><th>原因</th></tr></thead><tbody><tr><td>营销首页</td><td>SSG，发布时重建</td><td>页面少、公开、变更有编辑发布流程</td></tr><tr><td>类目页</td><td>静态生成热门类目，其余按需生成；短时缓存</td><td>需要索引，数量可控但库存变化频繁</td></tr><tr><td>商品详情</td><td>SSR 或按需静态生成；价格和库存局部客户端刷新</td><td>页面巨大，主体可缓存，实时字段不能长期静态</td></tr><tr><td>账户中心</td><td>CSR 外壳或受控 SSR</td><td>私有数据不可共享缓存，SEO 无价值</td></tr><tr><td>购物车抽屉</td><td>客户端交互</td><td>与会话强相关、交互频繁</td></tr></tbody></table><p>最终策略必须用真实流量、缓存命中和脚本成本验证。框架支持某模式不代表每条路由都应该开启。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>混合渲染能针对页面目标优化，但团队要维护多种缓存、数据加载和故障路径。服务端与客户端输出必须稳定一致，浏览器专用 API 只能在正确阶段访问。</p><p>需要为每类页面记录：HTML 生成地点、缓存键、最大陈旧时间、失效来源、用户数据边界、Hydration 范围和降级结果。否则“混合”会变成难以解释的隐式行为。</p><p>退出成本取决于页面是否把框架专有数据协议和运行时 API 深入业务层。保持数据契约和领域逻辑独立，可以降低从 SSR 转 CSR 或迁移托管平台的成本。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>纯内部工具没有索引需求且首屏可接受时，不必为 SSR 增加服务端运行时。</li><li>私有页面不能把用户 HTML 放进公共 CDN 缓存。</li><li>内容规模巨大、更新频繁时，不应默认全量 SSG。</li><li>仅用服务端 HTML 不能保证性能；Hydration、图片、字体和第三方脚本仍需预算。</li><li>不要把 ISR 当成一致性方案，关键库存和价格仍应从权威数据源确认。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>电商各类页面如何生成首屏 HTML</td></tr><tr><td>硬约束</td><td>商品主体可索引；私有数据不进共享缓存；库存最多陈旧 30 秒；LCP P75 小于 2.5 秒</td></tr><tr><td>候选</td><td>全站 CSR、全站 SSR、全量 SSG、按路由混合</td></tr><tr><td>决定</td><td>按页面混合，实时字段与静态主体分离</td></tr><tr><td>证据</td><td>页面数量、更新频率、搜索流量、CDN 命中、原型性能</td></tr><tr><td>接受代价</td><td>多种缓存和数据路径；增加 Hydration 与失效测试</td></tr><tr><td>退出路径</td><td>页面数据使用 HTTP 契约，不依赖托管商私有数据库接口</td></tr><tr><td>验证指标</td><td>LCP、INP、HTML 缓存命中、陈旧数据率、服务端错误率、构建时长</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>当搜索流量价值变化、页面数量或更新频率增长一个数量级、SSR 容量成本超过预算、Hydration 错误持续超标、CDN 命中低于目标，或框架和托管平台改变支持范围时复查。复查以页面类型为单位，不要求全站同时迁移。</p>',40)])])}const _=d(i,[["render",o]]);export{p as __pageData,_ as default};
